import Link from "next/link";
import { requireUser } from "@/lib/auth/guards";
import { db } from "@/lib/db";
import { artworkAction, storyAction } from "@/app/actions";
import { getMessages, getLocale } from "@/lib/i18n-server";
export const dynamic="force-dynamic";
const status:Record<string,Record<string,string>>={ru:{DRAFT:"Черновик",PENDING:"На модерации",REJECTED:"Отклонено",SCHEDULED:"Запланировано",PUBLISHED:"Опубликовано",HIDDEN:"Скрыто",DELETED:"Удалено"},en:{DRAFT:"Draft",PENDING:"In review",REJECTED:"Rejected",SCHEDULED:"Scheduled",PUBLISHED:"Published",HIDDEN:"Hidden",DELETED:"Deleted"},zh:{DRAFT:"草稿",PENDING:"审核中",REJECTED:"已拒绝",SCHEDULED:"已排期",PUBLISHED:"已发布",HIDDEN:"已隐藏",DELETED:"已删除"}};
export default async function Dashboard(){const u=await requireUser();const[works,stories,m,locale]=await Promise.all([db.artwork.findMany({where:{authorId:u.id,status:{not:"DELETED"}},include:{asset:true},orderBy:{createdAt:"desc"}}),db.story.findMany({where:{authorId:u.id,status:{not:"DELETED"}},include:{illustrations:{take:1,orderBy:{sortOrder:"asc"}}},orderBy:{createdAt:"desc"}}),getMessages(),getLocale()]);return <section className="section"><div className="section-title"><div><span className="eyebrow">{m.account}</span><h1>{m.myStudio}</h1></div><div><Link className="ghost" href="/dashboard/settings">Настройки</Link><Link className="button" href="/dashboard/stories/new">Новый рассказ</Link><Link className="button" href="/dashboard/uploads/new">{m.newArtwork}</Link></div></div><h2>Рассказы</h2><div className="list">{stories.map(s=><article className="row" key={s.id}>{s.illustrations[0]?<img src={`/api/stories/images/${s.illustrations[0].id}`} alt=""/>:<div className="story-placeholder">✦</div>}<div><b>{s.title}</b><span className={`status ${s.status.toLowerCase()}`}>{status[locale][s.status]}</span><p>{s.illustrations.length} иллюстраций</p></div><form action={storyAction}><input type="hidden" name="id" value={s.id}/>{s.status==="DRAFT"&&<><button name="op" value="publish">Опубликовать</button><button className="danger" name="op" value="delete">Удалить</button></>} {s.status==="PUBLISHED"&&<Link className="ghost" href={`/stories/${s.slug}`}>Открыть</Link>}</form></article>)}{!stories.length&&<div className="empty">Рассказов пока нет.</div>}</div><h2>Работы</h2><div className="list">{works.map(a=><article className="row" key={a.id}><img src={`/api/images/thumbnail/${a.id}`} alt=""/><div><b>{a.title}</b><span className={`status ${a.status.toLowerCase()}`}>{status[locale][a.status]}</span>{a.moderationNote&&<p>{a.moderationNote}</p>}</div><form action={artworkAction}><input type="hidden" name="id" value={a.id}/>{["DRAFT","REJECTED"].includes(a.status)&&<><Link className="ghost" href={`/dashboard/uploads/${a.id}/edit`}>{m.edit}</Link><button name="op" value="submit">{m.submit}</button><button className="danger" name="op" value="delete">{m.delete}</button></>}</form></article>)}{!works.length&&<div className="empty">{m.firstArtwork}</div>}</div></section>}
